const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),{JSDOM}=require('jsdom');
const base=path.resolve(__dirname,'../dist'),files=['core.js','demo.js','storage.js','presentation.js','intelligence.js','intelligence-ui.js','source-layouts.js','setup.js','experiments.js','date-range.js','workspace-motion.js','experiments-ui.js','dashboard.js'];
function app(demo=true){const dom=new JSDOM(fs.readFileSync(path.join(base,'index.html'),'utf8'),{runScripts:'outside-only',url:'http://localhost/'+(demo?'?demo=1&view=experiments':'')});const w=dom.window,d=w.document,memory={},downloads=[];let durable=0;
 w.structuredClone=structuredClone;w.Blob=Blob;w.HTMLElement.prototype.scrollIntoView=function(){};w.URL.createObjectURL=b=>{downloads.push(b);return 'blob:mock';};w.URL.revokeObjectURL=()=>{};w.HTMLAnchorElement.prototype.click=function(){};
 w.chrome={storage:{local:{get:async k=>{durable++;if(demo)throw Error('Demo touched durable storage');return k?{[k]:memory[k]}:memory;},set:async v=>{durable++;if(demo)throw Error('Demo wrote durable storage');Object.assign(memory,v);}}},runtime:{sendMessage:async()=>{throw Error('Viewer must not control extension');}}};
 for(const file of files)w.eval(fs.readFileSync(path.join(base,file),'utf8'));
 const click=text=>{const b=[...d.querySelectorAll('button')].find(b=>b.textContent===text);assert.ok(b,'Button '+text);b.click();};return {dom,w,d,memory,downloads,click,durable:()=>durable};
}
const tick=(n=40)=>new Promise(r=>setTimeout(r,n));
function reviewButton(document){const control=document.querySelector('.source-count-bar button.primary');assert.ok(control,'The setup form has a review action');assert.match(control.textContent,/^Review (?:[\d,]+ tests?|tests)$/,'Setup offers review before any submission');return control;}
const review=document=>reviewButton(document).click();
function editDateRange(w,d,from,to,{add=false,index=0,cancel=false}={}){
 const trigger=add?d.querySelector('[aria-label="Test values for date range"]'):d.querySelectorAll('.source-date-entry .vault-date-range-trigger')[index];assert.ok(trigger,'A single range control opens the calendar');assert.equal(trigger.disabled,false);trigger.click();
 const dialog=d.querySelector('.vault-date-range-dialog');assert.ok(dialog,'Range calendar opened');
 if(add)assert.deepEqual([...dialog.querySelectorAll('input[type=date]')].map(n=>n.value),['',''],'Adding a range starts a clean draft');
 for(const [label,value] of [['Start date',from],['End date',to]]){const n=dialog.querySelector('[aria-label="'+label+'"]');n.focus();n.value=value;n.dispatchEvent(new w.Event('change',{bubbles:true}));}
 const action=cancel?[...dialog.querySelectorAll('button')].find(n=>n.textContent==='Cancel'):dialog.querySelector('.vault-date-range-apply');assert.equal(action.disabled,false,'A complete valid pair can be applied');action.click();assert.equal(d.querySelector('.vault-date-range-dialog'),null);
}
const rangeLabels=d=>[...d.querySelectorAll('.source-date-entry .vault-date-range-trigger')].map(n=>n.textContent);
function currentJourney(document,expected){
 const journey=document.querySelector('nav[aria-label="Study progress"]');assert.ok(journey,'A study shows its place in the journey');
 assert.deepEqual([...journey.querySelectorAll('ol>li')].map(n=>n.dataset.stage),['setup','run','review']);
 assert.deepEqual([...journey.querySelectorAll('ol>li>strong')].map(n=>n.textContent),['Set up','Run tests','Review results']);
 const current=journey.querySelectorAll('[aria-current="step"]');assert.equal(current.length,1,'Only one stage is current');assert.equal(current[0].dataset.stage,expected);
 assert.equal(journey.querySelector('button,a,input,select'),null,'The stage indicator cannot submit a test or navigate to an unavailable future stage');
 return journey;
}
async function journeyStateTests(){
 const dom=new JSDOM('<main></main>',{runScripts:'outside-only',url:'chrome-extension://test-extension/index.html'}),w=dom.window,d=w.document,commands=[],scrolled=[];
 w.structuredClone=structuredClone;w.setInterval=()=>1;w.clearInterval=()=>{};w.HTMLElement.prototype.scrollIntoView=function(){scrolled.push(this);};
 for(const file of files.filter(file=>!['storage.js','dashboard.js'].includes(file)))w.eval(fs.readFileSync(path.join(base,file),'utf8'));
 const E=w.VaultExperiments,baseline=E.baseline(w.VaultDemo.create()[0]);baseline.demo=false;
 let plan;w.chrome={runtime:{sendMessage:async message=>{commands.push(message.action);assert.equal(message.action,'list','Reading progress and results must never run or resume a study');return {ok:true,experiments:[structuredClone(plan)],tabs:[]};}}};
 const store={demo:false,all:async()=>[],allBenchmarks:async()=>[]};
 const states=[['draft','queued','run'],['running','applying','run'],['pausing','capturing','run'],['paused','queued','run'],['needs-review','uncertain','run'],['complete','skipped','review'],['complete','queued','run'],['complete','uncertain','run'],['complete','capturing','run']];
 try{
  for(const [status,trialStatus,stage] of states){
   plan=E.create({id:'journey-state',name:'A saved study',baseline,dimensions:[{key:'momentum.period.1',values:'180'}]});plan.status=status;plan.trials[0].status=trialStatus;
   if(trialStatus==='uncertain')plan.trials[0].error='The source reply was interrupted.';
   const original=JSON.stringify(plan);await w.VaultExperimentsUI.render({target:d.querySelector('main'),store,runs:[],onOpen:()=>{throw Error('Progress must not open a fabricated result');},onExit:()=>{},table:()=>d.createElement('table'),download:()=>{}});
   d.querySelector('.experiment-card').click();const journey=currentJourney(d,stage),commandCount=commands.length;
   journey.querySelectorAll('li').forEach(node=>node.click());await tick();assert.equal(commands.length,commandCount,'Progress clicks only describe the current state');assert.equal(JSON.stringify(plan),original,'Journey rendering cannot change the saved study');
   if(stage==='review'){
    const view=[...d.querySelectorAll('button')].find(node=>node.textContent==='View results');assert.ok(view,'A completed study points to its results');view.click();await tick();
    const evidence=d.querySelector('.experiment-evidence');assert.equal(d.activeElement,evidence,'The result action moves keyboard focus into the ranking');assert.ok(scrolled.includes(evidence),'The result action brings the ranking into view');assert.equal(commands.length,commandCount,'Viewing results never submits, resumes, or reconciles');
   }
  }
 }finally{w.VaultExperimentsUI.dispose();dom.window.close();}
}
